int simge_bul(const char *ad) {
  if (!ad || !*ad) return -1;
  if (ad[0] == '*') {                      // 3.1: kullanıcının çizdiği simge
    int i = ozel_bul(ad + 1);
    return i < 0 ? -1 : OZEL_BAS + i;
  }
  for (int i = 0; i < SIMGE_SAYISI; i++)
    if (!strcmp(ad, SIMGELER[i].ad)) return i;
  return -1;
}
